SELECT r.id, r.kind, r.mime_type, r.size_bytes, r.storage, r.inline_body, r.compression, r.tenant_id, r.subtype, r.digest, r.uri, r.encryption_kms_key_id, r.redaction_policy_version, r.redacted, r.created_at, r.schema_ref, r.run_id, r.sequence FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM call_payload c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)